using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1WindowRoofInspect {
 public static object Run(){var root=Path.GetFullPath(Application.dataPath+"/../../..");var names=JArray.Parse(File.ReadAllText(root+"/SourceAssets/F1_WindowRoofDamage/models.json")).Select(q=>(string)q["name"]).ToArray();var results=names.Select(n=>{var go=GameObject.Find(n);return new{name=n,meshFilters=go.GetComponentsInChildren<MeshFilter>().Length,meshColliders=go.GetComponentsInChildren<MeshCollider>().Select(c=>new{mesh=c.sharedMesh?.name,sameMesh=c.sharedMesh==c.GetComponent<MeshFilter>()?.sharedMesh}).ToArray(),bounds=go.GetComponentsInChildren<Renderer>().Select(r=>new{minY=r.bounds.min.y,maxY=r.bounds.max.y}).ToArray()};}).ToArray();File.WriteAllText(root+"/Docs/Review/2026-11-13_1F_WindowRoofDamage/model_references.json",JsonConvert.SerializeObject(results,Formatting.Indented));return new{models=results.Length,meshColliders=results.Sum(r=>r.meshColliders.Length),meshColliderMismatches=results.Sum(r=>r.meshColliders.Count(c=>!c.sameMesh))};}
}
